/**
 * The Unicode emoji set the picker and the composer's `:` popup search, and the
 * remembered skin tone.
 *
 * The set itself (`./emojiData.ts`, generated by `scripts/gen-emoji-data.mjs`)
 * is about 1,900 emoji, so it is a lazy chunk: nothing loads it until a picker
 * or popup first asks, and `emojiCatalog()` is null until then.
 */

import { loadPref, savePref } from "../../lib/preferences";
import type { EMOJI_GROUPS } from "./emojiData";

export type EmojiGroupKey = (typeof EMOJI_GROUPS)[number][0];

export interface UnicodeEmoji {
  readonly char: string;
  /** Indices of the ZWJ segments that take a skin-tone modifier; "" for none. */
  readonly tone: string;
  /** Its shortcodes; the first is the name the `:` popup shows. */
  readonly names: readonly string[];
  /** Search keywords, space-separated: the curated words, then the names. */
  readonly keywords: string;
}

export interface EmojiCatalog {
  readonly groups: readonly {
    readonly key: EmojiGroupKey;
    readonly emoji: readonly UnicodeEmoji[];
  }[];
  /**
   * Every emoji by character: each skin-tone variant mapped to its base, plus
   * the U+FE0F-stripped form older pickers stored in Recent (unqualified).
   */
  readonly byChar: ReadonlyMap<string, UnicodeEmoji>;
}

/** No tone, then the five Fitzpatrick modifiers U+1F3FB..U+1F3FF. */
export const SKIN_TONES = ["", "\u{1F3FB}", "\u{1F3FC}", "\u{1F3FD}", "\u{1F3FE}", "\u{1F3FF}"];

const SKIN_TONE_PREF = "emojiSkinTone";

let catalog: EmojiCatalog | null = null;
let loading: Promise<EmojiCatalog> | null = null;

/** The loaded catalog, or null before `loadEmojiCatalog()` has resolved. */
export function emojiCatalog(): EmojiCatalog | null {
  return catalog;
}

/** Load the emoji set once; a failed load is retried on the next call. */
export function loadEmojiCatalog(): Promise<EmojiCatalog> {
  loading ??= import("./emojiData").then(
    (m) => (catalog = parseCatalog(m.EMOJI_GROUPS)),
    (err: unknown) => {
      loading = null;
      throw err;
    },
  );
  return loading;
}

function parseCatalog(groups: typeof EMOJI_GROUPS): EmojiCatalog {
  const byChar = new Map<string, UnicodeEmoji>();
  const parsed = groups.map(([key, rows]) => ({
    key,
    emoji: rows.split("\n").map((row) => {
      const [char = "", tone = "", names = "", words = ""] = row.split("|");
      const e = {
        char,
        tone,
        names: names.split(" "),
        keywords: words ? `${words} ${names}` : names,
      };
      for (let t = 0; t < SKIN_TONES.length; t++) byChar.set(withSkinTone(e, t), e);
      const bare = char.replaceAll("\u{FE0F}", "");
      if (!byChar.has(bare)) byChar.set(bare, e);
      return e;
    }),
  }));
  return { groups: parsed, byChar };
}

/**
 * The emoji in skin tone `tone` (an index into SKIN_TONES): the modifier goes
 * after the first code point of each toned segment, replacing the U+FE0F it
 * stands in for. The generator checks this rule against every skin-tone
 * sequence in Unicode's data.
 */
export function withSkinTone(e: UnicodeEmoji, tone: number): string {
  const mod = SKIN_TONES[tone];
  if (mod === undefined || mod === "" || e.tone === "") return e.char;
  const segs = e.char.split("‍");
  for (const i of e.tone) {
    const seg = segs[Number(i)] ?? "";
    const first = String.fromCodePoint(seg.codePointAt(0) ?? 0);
    segs[Number(i)] = first + mod + seg.slice(first.length).replace("️", "");
  }
  return segs.join("‍");
}

/**
 * Whether `query` (lowercase) is in the emoji's keywords. Underscores are
 * optional, so `thumbsup` finds `thumbs_up` the way Discord's shortcode does.
 */
export function emojiMatches(e: UnicodeEmoji, query: string): boolean {
  return e.keywords.includes(query) || e.keywords.replaceAll("_", "").includes(query);
}

/** The remembered skin tone, an index into SKIN_TONES. */
export function skinTone(): number {
  const tone = loadPref(SKIN_TONE_PREF, 0);
  return Number.isInteger(tone) && tone >= 0 && tone < SKIN_TONES.length ? tone : 0;
}

export function setSkinTone(tone: number): void {
  savePref(SKIN_TONE_PREF, tone);
}
